cd /Users/apple/Open/nlhack/video/tts && cat > probe.mjs <<'EOF'
import path from "node:path";
import { fileURLToPath } from "node:url";
import { env } from "@huggingface/transformers";
import { KokoroTTS } from "kokoro-js";

const here = path.dirname(fileURLToPath(import.meta.url));
env.cacheDir = path.join(here, ".cache");
const seen = new Set();
const tts = await KokoroTTS.from_pretrained("onnx-community/Kokoro-82M-v1.0-ONNX", {
  dtype: "fp32",
  device: "cpu",
  progress_callback: (p) => {
    if (p.status === "initiate" || p.status === "done") console.log(p.status, p.file);
  },
});
console.log("loaded");
const t0 = Date.now();
const a = await tts.generate("Meet Bot Company.", { voice: "af_heart", speed: 1 });
console.log("audio", a.audio.length, a.sampling_rate, (a.audio.length / a.sampling_rate).toFixed(2) + "s", Date.now() - t0, "ms");
EOF
(time node probe.mjs) 2>&1 | tail -30; du -sh .cache; find .cache -type f | xargs ls -la

