import path from "node:path";
import { fileURLToPath } from "node:url";
import { env } from "@huggingface/transformers";
import { KokoroTTS } from "kokoro-js";
const here = path.dirname(fileURLToPath(import.meta.url));
env.cacheDir = path.join(here, ".cache");
const tts = await KokoroTTS.from_pretrained("onnx-community/Kokoro-82M-v1.0-ONNX", { dtype: "fp32", device: "cpu" });
const SR = 24000;
const db = (x) => 20 * Math.log10(Math.max(x, 1e-9));
function frames(a, win, hop) { const out = []; for (let i = 0; i + win <= a.length; i += hop) out.push(i); return out; }
function f0track(a) {
  const win = Math.round(0.04 * SR), hop = Math.round(0.01 * SR);
  const res = [];
  for (const i of frames(a, win, hop)) {
    let e = 0; for (let k = 0; k < win; k++) e += a[i + k] ** 2;
    const rms = Math.sqrt(e / win);
    if (db(rms) < -42) { res.push([i / SR, 0, rms]); continue; }
    let best = 0, bl = 0;
    for (let lag = Math.round(SR / 400); lag <= Math.round(SR / 100); lag++) {
      let c = 0, e2 = 0; for (let k = 0; k + lag < win; k++) { c += a[i + k] * a[i + k + lag]; e2 += a[i + k + lag] ** 2; }
      const n = c / Math.sqrt(e * e2 + 1e-12);
      if (n > best) { best = n; bl = lag; }
    }
    res.push([i / SR, best > 0.55 ? SR / bl : 0, rms]);
  }
  return res;
}
function lastActive(a, thr = 0.003) { let j = a.length - 1; while (j > 0 && Math.abs(a[j]) < thr) j--; return j; }
function firstActive(a, thr = 0.003) { let j = 0; while (j < a.length && Math.abs(a[j]) < thr) j++; return j; }
const variants = process.argv.slice(2);
for (const t of variants) {
  const r = await tts.generate(t, { voice: "af_heart", speed: 1 });
  const a = r.audio;
  const s = firstActive(a), e = lastActive(a);
  const tr = f0track(a);
  const act = (e - s) / SR;
  // F0 of last 0.35s of active speech (voiced only), and mean F0 overall
  const tEnd = e / SR;
  const tail = tr.filter(([t0, f]) => f > 0 && t0 > tEnd - 0.45 && t0 < tEnd).map(([, f]) => Math.round(f));
  const all = tr.filter(([, f]) => f > 0).map(([, f]) => f);
  const mean = all.reduce((x, y) => x + y, 0) / all.length;
  console.log(JSON.stringify(t), `total ${(a.length / SR).toFixed(2)}s lead ${(s / SR * 1000) | 0}ms tail ${((a.length - e) / SR * 1000) | 0}ms active ${act.toFixed(2)}s meanF0 ${mean | 0} tailF0 [${tail.join(",")}]`);
